SELECT round(corr(`srfuzz_mut_34`.`t1`.`val1`, `srfuzz_mut_34`.`t1`.`val2`), corr(`srfuzz_mut_34`.`t1`.`val1`, `srfuzz_mut_34`.`t1`.`val2`)) AS `round(corr(val1, val2), corr(srfuzz_mut_34.t1.val1, srfuzz_mut_34.t1.val2))` FROM `srfuzz_mut_34`.`t1`;